var a=[["error","Elige la semilla x\u2080","Es el \xFAnico dato que aportas y no hay intervalo que verificar."],["error","Eval\xFAa f(x\u2099) y f\u2032(x\u2099)","Si |f\u2032(x\u2099)| es casi cero, frena: el paso se va a disparar."],["primario","Calcula x\u2099\u208A\u2081","Con la f\xF3rmula x\u2099\u208A\u2081 = x\u2099 \u2212 f(x\u2099)/f\u2032(x\u2099)."],["primario","Eval\xFAa f(x\u2099\u208A\u2081)","Si da cero exacto, termin\xF3: ese punto es la ra\xEDz."],["ok","Mide el desplazamiento","|\u0394x| = |x\u2099\u208A\u2081 \u2212 x\u2099|, y comp\xE1ralo con la tolerancia."],["neutro","Corre el \xEDndice","Si |\u0394x| todav\xEDa no llega a la tolerancia, la x vieja se reemplaza por la nueva."],["neutro","Vuelve al paso 2","Si se agota el m\xE1ximo de iteraciones, avisa que no convergi\xF3 y devuelve el \xFAltimo punto."]];export{a};
